import{bV as e,aL as a,u as r,G as d}from"./chunks/framework.BidoRKjm.js";const o="/assets/deployment-architecture.Bo1d2jiv.png",p=JSON.parse('{"title":"关于本站","description":"","frontmatter":{"title":"关于本站","outline":"deep","prev":false,"next":false,"comment":false,"articleUpdate":false},"headers":[],"relativePath":"about-site.md","filePath":"about/about-site.md","lastUpdated":1788192834000}'),l={name:"about-site.md"};function i(s,t,n,h,c,b){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="关于本站" tabindex="-1">关于本站 <a class="header-anchor" href="#关于本站" aria-label="Permalink to &quot;关于本站&quot;">​</a></h1><h2 id="👋-站点简介" tabindex="-1">👋 站点简介 <a class="header-anchor" href="#👋-站点简介" aria-label="Permalink to &quot;👋 站点简介&quot;">​</a></h2><p>本站是一个个人知识沉淀平台，目前主要记录计算机技术相关的学习笔记与实战经验。 未来也可能延伸至作者其他感兴趣的领域——这是一个持续生长的数字花园。</p><p>本站的核心理念是：<strong>持续输出、终身学习</strong>。</p><hr><h2 id="🧱-本站技术点" tabindex="-1">🧱 本站技术点 <a class="header-anchor" href="#🧱-本站技术点" aria-label="Permalink to &quot;🧱 本站技术点&quot;">​</a></h2><p>本站基于以下开源技术栈搭建：</p><table tabindex="0"><thead><tr><th>分类</th><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>静态站点生成器</td><td><strong>VitePress 2</strong></td><td>基于 Vite + Vue 3 的文档站点生成器，构建速度快，支持 Markdown 扩展、侧边栏自动生成</td></tr><tr><td>前端框架</td><td><strong>Vue 3</strong> + <strong>TypeScript</strong></td><td>类型安全，开发体验好，主题与自定义能力强</td></tr><tr><td>包管理器</td><td><strong>pnpm</strong></td><td>节省磁盘空间，安装依赖速度远快于 npm/yarn</td></tr><tr><td>自动侧边栏</td><td><code>vitepress-sidebar</code></td><td>根据目录结构自动生成学习笔记侧边栏，无需手动维护</td></tr><tr><td>主题</td><td><code>vitepress-theme-teek</code></td><td>一个轻量、简洁高效、灵活配置、易于扩展的 VitePress 主题</td></tr></tbody></table><hr><h2 id="🚀-部署架构" tabindex="-1">🚀 部署架构 <a class="header-anchor" href="#🚀-部署架构" aria-label="Permalink to &quot;🚀 部署架构&quot;">​</a></h2><p>本站采用<strong>源码私有 + 构建产物公开</strong>的双仓库分离架构，同时支持双平台部署：</p><blockquote><p>图片由千问 ai 生成</p></blockquote><p><img src="'+o+'" alt="部署架构"></p><h3 id="📍-双平台说明" tabindex="-1">📍 双平台说明 <a class="header-anchor" href="#📍-双平台说明" aria-label="Permalink to &quot;📍 双平台说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>部署平台</th><th>适用场景</th><th>访问特点</th></tr></thead><tbody><tr><td><strong>Cloudflare Pages</strong>（推荐）</td><td>日常主入口</td><td>全球 300+ 边缘节点 CDN 加速，国内访问速度快，内置图片自动压缩 / WebP 转码 / 移动端自适应</td></tr><tr><td><strong>GitHub Pages</strong>（兜底）</td><td>备份入口</td><td>与公开仓库绑定，作为 Pages 传统部署方案的兼容保留</td></tr></tbody></table><h3 id="🔐-为什么源码放在私有仓库" tabindex="-1">🔐 为什么源码放在私有仓库？ <a class="header-anchor" href="#🔐-为什么源码放在私有仓库" aria-label="Permalink to &quot;🔐 为什么源码放在私有仓库？&quot;">​</a></h3><ul><li>避免草稿、未完成内容、敏感配置过早暴露</li><li>公开仓库仅保留构建后的静态产物，降低风险</li><li>GitHub Actions 负责从私有仓库构建后推送到公开仓库，过程全自动</li></ul><hr><h2 id="📑-内容结构" tabindex="-1">📑 内容结构 <a class="header-anchor" href="#📑-内容结构" aria-label="Permalink to &quot;📑 内容结构&quot;">​</a></h2><p>本站主要包含以下板块：</p><table tabindex="0"><thead><tr><th>板块</th><th>路径</th><th>内容说明</th></tr></thead><tbody><tr><td>🏠 首页</td><td><code>/</code></td><td>站点入口、功能概览、快速导航</td></tr><tr><td>📚 学习笔记</td><td><code>/notes</code></td><td>各类系统化学习笔记，按技术领域分目录</td></tr><tr><td>🧑‍💻 关于我</td><td><code>/about-me</code></td><td>个人简介、技能栈、获奖经历、实战经历、联系方式</td></tr><tr><td>ℹ️ 关于本站</td><td><code>/about-site</code></td><td>即本文档，说明站点技术栈、架构、版权、参与方式等</td></tr></tbody></table><hr><h2 id="©️-版权与转载说明" tabindex="-1">©️ 版权与转载说明 <a class="header-anchor" href="#©️-版权与转载说明" aria-label="Permalink to &quot;©️ 版权与转载说明&quot;">​</a></h2><p>本站所有<strong>原创</strong>内容（包括但不限于文章、代码示例、插图）默认采用以下版权协议：</p><ul><li>非商业用途：可自由转载，但请在文章开头<strong>注明出处</strong>并附上本站链接。</li><li>商业用途：请先通过下方联系方式与作者沟通，获得书面授权后方可使用。</li></ul><p>本站引用的第三方技术文档、开源项目截图等内容，版权归其原作者/组织所有，引用处会尽可能标注来源，如有侵权请联系删除。</p><hr><h2 id="🤝-参与共建" tabindex="-1">🤝 参与共建 <a class="header-anchor" href="#🤝-参与共建" aria-label="Permalink to &quot;🤝 参与共建&quot;">​</a></h2><p>本站托管于 GitHub。如果你：</p><ul><li>发现文中存在错误、笔误或内容过时</li><li>希望补充某个技术点或案例</li><li>对站点交互/样式有改进建议</li></ul><p>欢迎通过以下方式参与：</p><ol><li><strong>GitHub Issues</strong> → 访问<a href="https://github.com/mobei-front/knowledge-base" target="_blank" rel="noreferrer">公开仓库</a>提交 Issue 说明问题</li><li><strong>邮件</strong> → 参考 <a href="/about-me#联系方式">关于我 → 联系方式</a> 页面中的邮箱</li></ol><hr><h2 id="🗓️-维护承诺" tabindex="-1">🗓️ 维护承诺 <a class="header-anchor" href="#🗓️-维护承诺" aria-label="Permalink to &quot;🗓️ 维护承诺&quot;">​</a></h2><ul><li>📌 本站内容会随着作者的学习进度持续更新，无法保证所有内容都是最新版本，但会尽力保持关键技术栈的准确性。</li><li>🛠️ 若遇到页面显示异常或资源加载失败，欢迎随时反馈。</li><li>🌱 记录过程比追求完美更重要，这里首先是一个<strong>个人成长的足迹</strong>，其次才是面向读者的分享平台。</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">感谢阅读</p><p>感谢你的访问，如果内容对你有帮助，欢迎分享给更多人，祝你也能在技术的道路上持续精进！</p></div>',37)])])}const g=e(l,[["render",i]]);export{p as __pageData,g as default};
